/** Material Symbols draw on a 960 grid whose y runs from -960 to 0, so the path is moved down into the viewport. */
private fun symbol(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = autoMirror)
        .addGroup(translationY = 960f)
        .addPath(addPathNodes(path), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
